//! Run with `zig build run-comments`.
//! Ordinary `//` comments occupy source bytes. File docs (`//!`) and declaration
//! docs (`///`) also need tokens, but none of these comments needs an AST node.
//! Emit one token per documentation line and terminate every comment with a
//! newline: `zast.AstContext.token` normally adds only a separating space.
//!
//! Expected output:
//! ```zig
//! // Generated by zast. Do not edit.
//! //! Generated declarations with API documentation.
//! /// The default answer.
//! /// Used when no explicit answer is supplied.
//! pub const answer: u32 = 42;
//! ```

const std = @import("std");
const zast = @import("zast");

pub fn main(init: std.process.Init) !void {
    const allocator = init.gpa;
    // Keep the header and its declarations together in one file context.
    var context: zast.AstContext = .{};
    defer context.deinit(allocator);
    _ = try context.addNode(allocator, .root, 0, undefined);

    // A normal header has no token; the renderer reads it before the first token.
    try context.source.appendSlice(allocator, "// Generated by zast. Do not edit.\n");

    // File documentation must precede the file's declarations.
    _ = try context.token(
        allocator,
        .container_doc_comment,
        "//! Generated declarations with API documentation.",
    );
    try context.source.append(allocator, '\n');

    // Consecutive doc tokens document the declaration emitted immediately after.
    for ([_][]const u8{
        "/// The default answer.",
        "/// Used when no explicit answer is supplied.",
    }) |line| {
        _ = try context.token(allocator, .doc_comment, line);
        try context.source.append(allocator, '\n');
    }
    const declaration: zast.Declaration = .{
        .type_expression = .{ .identifier = "u32" },
        .value = .{ .integer_literal = "42" },
    };
    try declaration.emit(allocator, &context, "answer", .public);

    // The finished AST owns its node buffers but borrows its source allocation.
    var tree = try context.finish(allocator);
    const source = tree.source;
    defer allocator.free(source);
    defer tree.deinit(allocator);
    const rendered = try tree.renderAlloc(allocator);
    defer allocator.free(rendered);
    try std.Io.File.stdout().writeStreamingAll(init.io, rendered);
}
